# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.2/ankra-cli-darwin-arm64"
      sha256 "eea894fd045a93358f3b903300d4c0409ceeb1021eb3c5d7ea3edb6e56fffa3e"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.2/ankra-cli-darwin-amd64"
      sha256 "120dc38e4563c5074208af988b1da4fe4cd01a8446b3a9b357282d2fe25c2fd9"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.2/ankra-cli-linux-arm64"
      sha256 "1a0169c28e0a3d7075fb553e5b15720b82c103599d70f4ec0a71f982b3225a1d"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.2/ankra-cli-linux-amd64"
